using System.Security.Cryptography;
using System.Text.Json;
namespace Storloom.Core.Chats;

internal sealed record NativeSnapshot(string Id,string Source,ChatPlatform Platform,DateTimeOffset Created,ArchiveFileEntry[] Files,string[] EmptyDirectories);
internal sealed partial class ArchiveStore {
    private sealed record NativeRoot(int Version,string Id,string Source,ChatPlatform Platform,DateTimeOffset Created,string[] Pages,string[] EmptyDirectories,int FileCount=0,long ContentBytes=0);
    private static void WriteNativeSnapshot(Writer writer,NativeSnapshot snapshot,bool current){
        var pages=new List<string>();foreach(var group in snapshot.Files.GroupBy(f=>Convert.ToHexStringLower(SHA256.HashData(System.Text.Encoding.UTF8.GetBytes(f.Path)))[..2]).OrderBy(g=>g.Key,StringComparer.Ordinal)){
            byte[] bytes=JsonSerializer.SerializeToUtf8Bytes(group.OrderBy(f=>f.Path,StringComparer.Ordinal).ToArray());string page="native-manifest-pages/"+Convert.ToHexStringLower(SHA256.HashData(bytes))+".json";writer.Bytes(page,bytes);pages.Add(page);
        }
        byte[] root=JsonSerializer.SerializeToUtf8Bytes(new NativeRoot(2,snapshot.Id,snapshot.Source,snapshot.Platform,snapshot.Created,pages.ToArray(),snapshot.EmptyDirectories,snapshot.Files.Length,snapshot.Files.Sum(f=>f.Length)));writer.Bytes("native-snapshots/"+snapshot.Id+".json",root);if(current)writer.Bytes("native-current.json",root);
    }
    private NativeSnapshot ReadNativeSnapshot(Stream input){
        using var json=JsonDocument.Parse(input);if(!json.RootElement.TryGetProperty("Pages",out _))return json.RootElement.Deserialize<NativeSnapshot>()??throw new InvalidDataException("Invalid native snapshot.");
        var manifest=json.RootElement.Deserialize<NativeRoot>()??throw new InvalidDataException("Invalid native snapshot root.");if(manifest.Version!=2||manifest.Pages.Length>256||manifest.Pages.Distinct(StringComparer.Ordinal).Count()!=manifest.Pages.Length)throw new InvalidDataException("Invalid native manifest pages.");
        var files=new List<ArchiveFileEntry>();foreach(string page in manifest.Pages){if(!page.StartsWith("native-manifest-pages/",StringComparison.Ordinal)||!page.EndsWith(".json",StringComparison.Ordinal)||!ArchiveQueryCache.ValidId(Path.GetFileNameWithoutExtension(page)))throw new InvalidDataException("Invalid native manifest page reference.");using var source=OpenFile(page);files.AddRange(JsonSerializer.Deserialize<ArchiveFileEntry[]>(source)??throw new InvalidDataException("Invalid native manifest page."));}
        return new(manifest.Id,manifest.Source,manifest.Platform,manifest.Created,files.ToArray(),manifest.EmptyDirectories);
    }
    internal NativeSnapshot BackupNative(string source,ChatPlatform platform,IProgress<ScanProgress>? progress=null,CancellationToken cancellation=default,bool checkClients=true){
        if(query.MessageCount!=0)throw new IOException("A reading archive cannot be used as a native backup.");
        source=PathPolicy.Normalize(source);if(source.Equals(root,StringComparison.OrdinalIgnoreCase)||PathPolicy.Under(source,root)||PathPolicy.Under(root,source))throw new IOException("Native source and compact backup must be separate.");
        string[] clients=checkClients?(platform==ChatPlatform.QQ?["QQ"]:["Weixin","WeChat"]):[];var plan=new TransferService(Workers).Plan(source,root+".plan",processes:clients,cancellation:cancellation,progress:progress);
        string proof=JsonFiles.Hash(new{source,plan.Files,plan.EmptyDirectories}).ToLowerInvariant();try{var current=NativeCurrent();if(current.Platform!=platform||!source.Equals(current.Source,StringComparison.OrdinalIgnoreCase))throw new IOException("Native backup belongs to another account source.");if(current.Id==proof&&!File.Exists(Path.Combine(root,".write-task.json"))){MarkNative();return current;}}catch(FileNotFoundException){}using var writer=BeginWrite(cancellation,proof,progress);var entries=new List<ArchiveFileEntry>();long processed=0,total=plan.Files.Sum(f=>f.Stamp.Bytes);int done=0;
        foreach(var file in plan.Files){OperationPause.Check(cancellation);string path=TransferService.Child(source,file.RelativePath);PathPolicy.AssertNoLinks(path);if(NativeFile.ReadStamp(path)!=file.Stamp)throw new IOException("Native source changed since planning.");
            using var input=new FileStream(path,FileMode.Open,FileAccess.Read,FileShare.Read);long before=processed;var entry=writer.Put("native/"+file.RelativePath.Replace('\\','/'),input,file.Stamp,advance:n=>{processed+=n;progress?.Report(new("archive-native-pack",done,processed,total,plan.Files.Count,file.RelativePath));});if(processed==before)processed+=file.Stamp.Bytes;
            if(NativeFile.ReadStamp(path)!=file.Stamp)throw new IOException("Native source changed during backup.");entries.Add(entry with{Path=file.RelativePath.Replace('\\','/')});done++;progress?.Report(new("archive-native-pack",done,processed,total,plan.Files.Count,file.RelativePath));
        }
        if(clients.Length>0&&CleanupEngine.RunningProcesses(new CleanupRule{Processes=clients}).Length>0)throw new IOException("Close the native client before publishing its backup.");
        foreach(var file in plan.Files)if(NativeFile.ReadStamp(TransferService.Child(source,file.RelativePath))!=file.Stamp)throw new IOException("Native source changed before publication.");
        var snapshot=new NativeSnapshot(proof,source,platform,DateTimeOffset.UtcNow,entries.ToArray(),plan.EmptyDirectories.Select(p=>p.Replace('\\','/')).ToArray());WriteNativeSnapshot(writer,snapshot,true);MarkNative();writer.Complete(new(proof,"complete",plan.Files.Count,0,0,plan.Files.Count,total));MarkNative();return snapshot;
    }
    internal static bool IsNative(string directory)=>JsonFiles.Read<Configuration>(Path.Combine(directory,"archive.json")).Kind=="native";
    private void MarkNative(){string path=Path.Combine(root,"archive.json");PathPolicy.AssertNoLinks(path);var config=JsonFiles.Read<Configuration>(path);if(config.Kind!="native")JsonFiles.Write(path,config with{Kind="native"});}
    internal sealed record NativeSnapshotInfo(string Id,DateTimeOffset Created,int Files,long Bytes);
    internal IReadOnlyList<NativeSnapshotInfo> NativeHistory(){var result=new List<NativeSnapshotInfo>();foreach(var file in query.NativeSnapshotFiles()){using var input=OpenFile(file.Path);using var doc=JsonDocument.Parse(input);if(doc.RootElement.TryGetProperty("Pages",out _)){var manifest=doc.RootElement.Deserialize<NativeRoot>()??throw new InvalidDataException("Invalid snapshot.");result.Add(new(manifest.Id,manifest.Created,manifest.FileCount,manifest.ContentBytes));}else{var snapshot=doc.RootElement.Deserialize<NativeSnapshot>()??throw new InvalidDataException("Invalid snapshot.");result.Add(new(snapshot.Id,snapshot.Created,snapshot.Files.Length,snapshot.Files.Sum(f=>f.Length)));}}return result.OrderByDescending(s=>s.Created).ToArray();}
    internal NativeSnapshot NativeCurrent(){using var input=OpenFile("native-current.json");return ReadNativeSnapshot(input);}
    internal string RestoreNative(string destination,IProgress<ScanProgress>? progress=null,CancellationToken cancellation=default,string? snapshotId=null){
        using var lease=Lease(readOnly:true);NativeSnapshot snapshot;if(snapshotId==null)snapshot=NativeCurrent();else{if(!ArchiveQueryCache.ValidId(snapshotId))throw new InvalidDataException("Invalid snapshot ID.");using var input=OpenFile("native-snapshots/"+snapshotId+".json");snapshot=ReadNativeSnapshot(input);}
        destination=PathPolicy.Normalize(destination);if(Directory.Exists(destination)||File.Exists(destination)||PathPolicy.Under(destination,root)||PathPolicy.Under(root,destination)||destination.Equals(root,StringComparison.OrdinalIgnoreCase)||destination.Equals(snapshot.Source,StringComparison.OrdinalIgnoreCase)||PathPolicy.Under(destination,snapshot.Source)||PathPolicy.Under(snapshot.Source,destination))throw new IOException("Restore into a new directory separate from the source and backup.");PathPolicy.AssertNoLinks(Path.GetDirectoryName(destination)!);
        foreach(var file in snapshot.Files){ArchiveQueryCache.ValidatePath(file.Path);if(file.Sha256==null||!ArchiveQueryCache.ValidId(file.Sha256))throw new InvalidDataException("Native file digest missing.");}foreach(var directory in snapshot.EmptyDirectories)if(directory!=".")ArchiveQueryCache.ValidatePath(directory);
        if(snapshot.Files.Select(f=>f.Path).Distinct(StringComparer.OrdinalIgnoreCase).Count()!=snapshot.Files.Length)throw new InvalidDataException("Duplicate native restore paths.");long total=snapshot.Files.Sum(f=>f.Length),doneBytes=0;int done=0;if(new DriveInfo(Path.GetPathRoot(destination)!).AvailableFreeSpace<checked(total+1024*1024))throw new IOException("Insufficient space for restored native files.");Directory.CreateDirectory(destination);PathPolicy.AssertNoLinks(destination);
        foreach(var file in snapshot.Files){OperationPause.Check(cancellation);string path=TransferService.Child(destination,file.Path);EnsureParent(destination,file.Path);using(var input=new ChunkStream(file.Length,query.FileParts(file.Version),id=>ReadObject(id),()=>{}))using(var output=new FileStream(path,FileMode.CreateNew,FileAccess.Write,FileShare.None)){byte[] buffer=new byte[1024*1024];int count;while((count=input.Read(buffer))>0){OperationPause.Check(cancellation);output.Write(buffer,0,count);doneBytes+=count;progress?.Report(new("archive-native-restore",done,doneBytes,total,snapshot.Files.Length,file.Path));}output.Flush(true);}
            using(var verified=File.OpenRead(path))if(Convert.ToHexStringLower(TransferService.Hash(verified,cancellation))!=file.Sha256)throw new InvalidDataException("Restored native file verification failed.");if(file.SourceStamp!=null)File.SetLastWriteTimeUtc(path,new DateTime(file.SourceStamp.WriteUtcTicks,DateTimeKind.Utc));done++;
        }
        foreach(string directory in snapshot.EmptyDirectories)if(directory!="."){EnsureParent(destination,directory+"/.directory");}progress?.Report(new("archive-native-restore",done,doneBytes,total,snapshot.Files.Length));return destination;
    }
}
